          disableDefaultUI: true,
          scaleControl: true,
          gestureHandling: "greedy",
        });

        // Register custom Google Hybrid Satellite & Street ImageMapTypes (Direct Google Satellite Servers without billing watermark)
        const googleHybridTiles = new maps.ImageMapType({
          getTileUrl: (coord: any, zoom: number) => {
            const sub = Math.abs((coord.x + coord.y) % 4);
            return `https://mt${sub}.google.com/vt/lyrs=y&x=${coord.x}&y=${coord.y}&z=${zoom}`;
          },
          tileSize: new maps.Size(256, 256),
          maxZoom: 20,
          name: "Google Satellite",
        });

        const googleStreetTiles = new maps.ImageMapType({
          getTileUrl: (coord: any, zoom: number) => {
            const sub = Math.abs((coord.x + coord.y) % 4);
            return `https://mt${sub}.google.com/vt/lyrs=m&x=${coord.x}&y=${coord.y}&z=${zoom}`;
          },
          tileSize: new maps.Size(256, 256),
          maxZoom: 20,
          name: "Google Street",
        });

        map.mapTypes.set("googleHybrid", googleHybridTiles);
        map.mapTypes.set("googleStreet", googleStreetTiles);
        map.setMapTypeId(mapLayerMode === "satellite" ? "googleHybrid" : "googleStreet");

        googleMapRef.current = map;
        setMapEngine("google");

        map.addListener("tilesloaded", () => {
          const errorAnchors = document.querySelectorAll<HTMLElement>(
            'a[href*="error-messages"], a[href*="developers.google.com/maps"], .dismissButton'
          );
          errorAnchors.forEach((el) => {
            let curr: HTMLElement | null = el as HTMLElement;
            while (
              curr &&
              curr.parentElement &&
              !curr.parentElement.classList.contains("gm-style") &&
              curr.parentElement !== mapContainerRef.current &&
              curr !== document.body
            ) {
              curr = curr.parentElement;
            }
            if (curr && curr !== document.body) {
              curr.remove();
            }
          });
        });

        // Map Click to Add New Boundary Point
        map.addListener("click", (e: any) => {
          if (isClosedRef.current && pointsRef.current.length >= 3) return;

          const newPt: LatLngPoint = { lat: e.latLng.lat(), lng: e.latLng.lng() };
          const previous = pointsRef.current;

          // Clicking near the first vertex closes an existing polygon
          if (previous.length >= 3 && getEdgeDistance(previous[0], newPt).feet < 30) {
            setIsDrawingClosed(true);
            isClosedRef.current = true;
            if (googleRubberBandRef.current) {
              googleRubberBandRef.current.setMap(null);
              googleRubberBandRef.current = null;
            }
            setCursorDistanceFt(null);
            return;
          }

          const updated = [...previous, newPt];
          setHistory((h) => [...h, previous]);
          setRedoHistory([]);
          pointsRef.current = updated;
          setPoints(updated);
        });

        // Live Rubber-Band Guide Line to Mouse Cursor
        map.addListener("mousemove", (e: any) => {
          const curPts = pointsRef.current;
          if (curPts.length > 0 && !isClosedRef.current) {
            const lastPt = curPts[curPts.length - 1];
            const mousePt = { lat: e.latLng.lat(), lng: e.latLng.lng() };

            if (!googleRubberBandRef.current) {
              googleRubberBandRef.current = new maps.Polyline({
                path: [lastPt, mousePt],
                strokeColor: "#10B981",
                strokeWeight: 2,
                strokeOpacity: 0.85,
                map,
                clickable: false,
              });
            } else {
              googleRubberBandRef.current.setPath([lastPt, mousePt]);
            }

            const dist = getEdgeDistance(lastPt, mousePt);
            setCursorDistanceFt(dist.feet);
          } else if (googleRubberBandRef.current) {
            googleRubberBandRef.current.setMap(null);
            googleRubberBandRef.current = null;
            setCursorDistanceFt(null);
          }
        });

        map.addListener("mouseout", () => {
          if (googleRubberBandRef.current) {
            googleRubberBandRef.current.setMap(null);
            googleRubberBandRef.current = null;
          }
          setCursorDistanceFt(null);
        });

        map.addListener("dblclick", () => {
          if (pointsRef.current.length >= 3) {
            setIsDrawingClosed(true);
            isClosedRef.current = true;
            if (googleRubberBandRef.current) {
              googleRubberBandRef.current.setMap(null);
              googleRubberBandRef.current = null;
            }
            setCursorDistanceFt(null);
          }
        });

        renderGoogleParcel(pointsRef.current);
      })
      .catch callback

